"use client";
// @zeus-internal
import { Mic, MicOff, PhoneOff } from "lucide-react";
import { useId, useRef } from "react";
import { ArtemisActionSwapIcon } from "../../../foundations/action-swap";
import { ArtemisButton } from "../../../foundations/button";
import { BAR_COUNT, COPY, useConversation, useWave } from "./01-conversation/use-conversation";
const BARS = Array.from({ length: BAR_COUNT }, (_, i) => 7 + i * 10);
export default function VoiceConversationConversation() {
    const { status, muted, start, stop, toggleMute } = useConversation();
    const headingId = useId();
    const svgRef = useRef<SVGSVGElement>(null);
    useWave(status, muted, svgRef);
    const idle = status === "idle" || status === "ended";
    const copy = muted && status === "listening" ? { ...COPY.listening, label: "Microphone muted" } : COPY[status];
    return (<>
      <div className="art:flex art:w-full art:flex-col art:items-center art:gap-4">
        <section aria-labelledby={headingId} className="art:w-full art:max-w-sm art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:text-foreground">
          <div className="art:flex art:items-center art:justify-between art:gap-3">
            <h2 id={headingId} className="art:text-4xl art:font-medium">
              {"Voice conversation"}
            </h2>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-audio-lines art:size-4 art:text-muted-foreground" aria-hidden="true">
              <path d="M2 10v3"/>
              <path d="M6 6v11"/>
              <path d="M10 3v18"/>
              <path d="M14 8v7"/>
              <path d="M18 5v13"/>
              <path d="M22 10v3"/>
            </svg>
          </div>
          <div aria-hidden="true" className="art:flex art:h-28 art:items-center art:justify-center art:gap-1.5">
            <svg ref={svgRef} aria-hidden="true" viewBox="0 0 214 88" className="art:h-22 art:w-56 art:overflow-visible art:text-foreground">
              {BARS.map((x) => (<line key={x} x1={x} x2={x} stroke="currentColor" strokeWidth="5" strokeLinecap="round" y1="44" y2="44"/>))}
            </svg>
          </div>
          <div className="art:text-center">
            <output className="art:block art:text-sm art:font-medium">{copy.label}</output>
            <div className="art:mt-2 art:flex art:min-h-12 art:items-start art:justify-center art:text-sm art:leading-relaxed art:text-muted-foreground">{copy.hint}</div>
          </div>
          <div className="art:mt-4 art:flex art:items-center art:justify-center art:gap-3">
            {idle ? (<ArtemisButton size="none" className="art:px-4 art:h-9" onClick={start}>
                <Mic className="art:size-4" aria-hidden="true"/>
                {status === "ended" ? "Start again" : "Start talking"}
              </ArtemisButton>) : (<>
                <ArtemisButton variant="tertiary" size="icon" className="art:size-9 art:h-9" aria-label={muted ? "Unmute microphone" : "Mute microphone"} aria-pressed={muted} disabled={status === "connecting"} onClick={toggleMute}>
                  <ArtemisActionSwapIcon value={muted ? "off" : "on"}>{muted ? <MicOff className="art:size-4" aria-hidden="true"/> : <Mic className="art:size-4" aria-hidden="true"/>}</ArtemisActionSwapIcon>
                </ArtemisButton>
                <ArtemisButton size="none" className="art:px-4 art:h-9" whileHover={undefined} whileTap={undefined} onClick={stop}>
                  <PhoneOff className="art:size-4" aria-hidden="true"/>
                  {status === "connecting" ? "Cancel" : "End chat"}
                </ArtemisButton>
              </>)}
          </div>
        </section>
        <p className="art:text-xs art:text-muted-foreground">{"Interactive demo \u00B7 No microphone access"}</p>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { useCallback, useEffect, useRef, useState, type RefObject } from "react";
export type ConversationStatus = "idle" | "ended" | "connecting" | "listening" | "thinking" | "speaking";
export const COPY: Record<ConversationStatus, {
    label: string;
    hint: string;
}> = {
    idle: { label: "Ready when you are", hint: "Talk through an idea, one thought at a time." },
    ended: { label: "Conversation ended", hint: "Start again whenever you\u2019re ready." },
    connecting: { label: "Connecting\u2026", hint: "Take your time. I\u2019m here." },
    listening: { label: "Listening to you", hint: "\u201CHelp me turn this idea into a first draft.\u201D" },
    thinking: { label: "Thinking\u2026", hint: "Finding a good place to start\u2026" },
    speaking: { label: "Speaking", hint: "\u201COf course. What\u2019s the one thing you want it to do?\u201D" },
};
const NEXT: Partial<Record<ConversationStatus, [
    ConversationStatus,
    number
]>> = {
    connecting: ["listening", 900],
    listening: ["thinking", 5000],
    thinking: ["speaking", 1600],
    speaking: ["listening", 5000],
};
export function useConversation() {
    const [status, setStatus] = useState<ConversationStatus>("idle");
    const [muted, setMuted] = useState(false);
    const held = muted && status === "listening";
    useEffect(() => {
        const step = NEXT[status];
        if (!step || held)
            return;
        const id = window.setTimeout(() => setStatus(step[0]), step[1]);
        return () => window.clearTimeout(id);
    }, [status, held]);
    const start = useCallback(() => setStatus("connecting"), []);
    const stop = useCallback(() => {
        setStatus("ended");
        setMuted(false);
    }, []);
    const toggleMute = useCallback(() => setMuted((m) => !m), []);
    return { status, muted, start, stop, toggleMute };
}
export const BAR_COUNT = 21;
const MID = 44;
const TAU = 0.1;
const M0 = 0.513;
const SLOW_RATE = 0.46;
const G = 1.0024;
const K1 = 0.4206;
const W1 = 4.0084;
const K2 = 0.3091;
const W2 = -2.5299;
const C = [0.148, -0.3069, 0.057, -0.192] as const;
function shape(i: number, m: number): number {
    const x = (i - 10) / 10;
    const a1 = K1 * i - W1 * m;
    const a2 = K2 * i - W2 * m;
    return Math.exp(-G * x * x) * (1 + C[0] * Math.sin(a1) + C[1] * Math.cos(a1) + C[2] * Math.sin(a2) + C[3] * Math.cos(a2));
}
const ENV_STEP = 0.05;
const ENV = [
    2.1, 7.2, 25.9, 28.7, 30.5, 31.1, 32.3, 32.6, 32.0, 31.2, 29.6, 28.0, 26.0, 24.9, 22.9, 22.0, 21.1, 20.9, 21.0, 21.2,
    21.9, 22.2, 22.8, 23.0, 22.8, 22.3, 21.0, 19.7, 17.3, 15.7, 12.7, 10.5, 8.0, 6.8, 5.2, 4.5, 4.8, 5.5, 7.3, 9.1, 12.2,
    14.1, 17.8, 20.3, 23.2, 24.5, 26.6, 27.4, 27.8, 27.7, 26.9, 26.3, 25.0, 24.3, 23.4, 22.8, 22.8, 23.0, 23.6, 24.5,
    25.7, 26.4, 27.7, 28.4, 28.6, 28.4, 27.5, 26.2, 23.8, 22.1, 18.4, 16.0, 12.3, 10.5, 7.7, 6.0, 4.9, 4.8, 5.2, 6.1, 8.0,
    9.5, 12.3, 14.4, 17.0, 18.3, 20.4, 21.4, 22.1, 22.2, 21.9, 21.8, 21.0, 20.6, 20.4, 20.2, 20.8, 21.4, 22.7, 24.1, 23.0,
] as const;
function envelope(tau: number): number {
    const x = Math.max(0, tau) / ENV_STEP;
    const j = Math.min(Math.floor(x), ENV.length - 2);
    const f = Math.min(1, x - j);
    return (ENV[j] ?? 0) * (1 - f) + (ENV[j + 1] ?? 0) * f;
}
function level(status: ConversationStatus, muted: boolean, tau: number): number {
    switch (status) {
        case "idle":
        case "ended":
            return 0;
        case "connecting":
            return 5.6;
        case "thinking":
            return 5.5;
        case "listening":
            return muted ? 0 : envelope(tau);
        case "speaking":
            return envelope(tau);
    }
}
export function useWave(status: ConversationStatus, muted: boolean, svg: RefObject<SVGSVGElement | null>) {
    const statusRef = useRef(status);
    const mutedRef = useRef(muted);
    statusRef.current = status;
    mutedRef.current = muted;
    useEffect(() => {
        let raf = 0;
        let last: number | null = null;
        let phase: ConversationStatus | null = null;
        let phaseHeld = false;
        let phaseStart = 0;
        let m = M0;
        let lvl = 0;
        let wasQuiet = true;
        const frame = (now: number) => {
            const st = statusRef.current;
            const isMuted = mutedRef.current;
            const quiet = st === "idle" || st === "ended";
            const dt = last === null ? 1 / 60 : Math.min(0.1, (now - last) / 1000);
            last = now;
            if (wasQuiet && !quiet)
                m = M0;
            else if (!quiet)
                m += dt * (st === "listening" || st === "speaking" ? 1 : SLOW_RATE);
            wasQuiet = quiet;
            const held = isMuted && st === "listening";
            if (st !== phase || (phaseHeld && !held))
                phaseStart = now;
            phase = st;
            phaseHeld = held;
            const tau = (now - phaseStart) / 1000;
            lvl += (level(st, isMuted, tau) - lvl) * (1 - Math.exp(-dt / TAU));
            const lines = svg.current?.querySelectorAll("line");
            if (lines) {
                const flat = quiet && lvl < 0.002;
                if (flat)
                    lvl = 0;
                lines.forEach((line, i) => {
                    const half = flat ? 0 : (lvl * shape(i, m)) / 2;
                    line.setAttribute("y1", String(MID - half));
                    line.setAttribute("y2", String(MID + half));
                });
            }
            raf = requestAnimationFrame(frame);
        };
        raf = requestAnimationFrame(frame);
        return () => cancelAnimationFrame(raf);
    }, [svg]);
}
